/* eslint-disable @typescript-eslint/no-unsafe-return */
import { ref } from 'vue';
import { i18n } from 'src/boot/i18n';
export default {
  //add dragging label for custom dragging label (non-reactive)
  draggingLabel: '',
  data() {
    return {
      tableColumnsOriginal: [],
      draggingLabelKey: '',
      indexToMove: -1,
      oldIndex: '',
      tableColumns: '',
      tableScrollInterval: null,
      lastSwappedIndex: -1,
      lastX: -1,
      tableId: '',
      tableRef: '',
      isDragging: ref(false),
      isColumnDragging: ref(false),
      preventDragDropColumns: [],
    };
  },
  computed: {
    getIsDragging() {
      return this.isDragging ? true : false;
    },
  },
  methods: {
    canDragDropColumn(column) {
      if (!column) {
        return;
      }
      return !this.preventDragDropColumns.includes(column.name);
    },
    removeScrollDiv() {
      document.getElementById(this.tableId + '-scroll-right').remove();
      document.getElementById(this.tableId + '-scroll-left').remove();
    },
    generateScrollDiv() {
      const table = document.getElementById(this.tableId);
      const scrollLeft = document.createElement('div');
      scrollLeft.classList.add('table-scroll-area-left');
      scrollLeft.id = this.tableId + '-scroll-left';
      const scrollRight = document.createElement('div');
      scrollRight.classList.add('table-scroll-area-right');
      scrollRight.id = this.tableId + '-scroll-right';
      scrollLeft.addEventListener('dragenter', (event) => {
        event.preventDefault();
        this.scrollDragEnter(-2);
      });
      scrollLeft.addEventListener('dragleave', (event) => {
        event.preventDefault();
        this.scrollDragLeave();
      });
      scrollRight.addEventListener('dragenter', (event) => {
        event.preventDefault();
        this.scrollDragEnter(2);
      });
      scrollRight.addEventListener('dragleave', (event) => {
        event.preventDefault();
        this.scrollDragLeave();
      });

      table.append(scrollLeft);
      table.append(scrollRight);
    },

    setPreventDragDropColumns(columns) {
      if (!columns) {
        return;
      }
      this.preventDragDropColumns = columns;
    },
    initailizeDragColumnsById(id) {
      this.tableId = id;
    },
    initailizeDragColumnsByRef(tableRef) {
      this.tableRef = tableRef;
      const table = this.tableRef.$el;
      this.tableId = table.id;
    },
    setDrggingLabelKey(key) {
      this.draggingLabelKey = key;
    },
    getDraggingLabelKey() {
      const key = this.draggingLabelKey;
      if (!key) return 'label';
      return key;
    },
    initDragDropColumns(tableId, LabelKey = 'label', columnsName = []) {
      this.initailizeDragColumnsById(tableId);
      this.setDrggingLabelKey(LabelKey);
      this.setPreventDragDropColumns(columnsName);
    },
    handleDrop(e, index) {
      this.scrollDragLeave();
      document
        .getElementsByTagName('html')[0]
        .classList.remove('draggable-column');
      // const event = new CustomEvent(this.tableId + '-column-drop', {detail: this.tableColumns});
      // document.dispatchEvent(event);
    },
    scrollDragEnter(speed) {
      this.tableScrollInterval = setInterval(() => {
        const content = document
          .getElementById(this.tableId)
          ?.querySelector('div');
        if (content) {
          content.scrollLeft += speed;
        }
      });
    },
    scrollDragLeave() {
      clearInterval(this.tableScrollInterval);
    },
    onDragStart(event, tableColumns, indexToMove) {
      this.isColumnDragging = true;
      //saved the original columns for comparasion
      this.tableColumnsOriginal = JSON.stringify(tableColumns);

      table.append(scrollLeft);
      table.append(scrollRight);
    },

    setPreventDragDropColumns(columns) {
      if (!columns) {
        return;
      }
      this.preventDragDropColumns = columns;
    },
    initailizeDragColumnsById(id) {
      this.tableId = id;
    },
    initailizeDragColumnsByRef(tableRef) {
      this.tableRef = tableRef;
      const table = this.tableRef.$el;
      this.tableId = table.id;
    },
    setDrggingLabelKey(key) {
      this.draggingLabelKey = key;
    },
    getDraggingLabelKey() {
      const key = this.draggingLabelKey;
      if (!key) return 'label';
      return key;
    },
    initDragDropColumns(tableId, LabelKey = 'label', columnsName = []) {
      this.initailizeDragColumnsById(tableId);
      this.setDrggingLabelKey(LabelKey);
      this.setPreventDragDropColumns(columnsName);
    },
    handleDrop(e, index) {
      this.scrollDragLeave();
      document
        .getElementsByTagName('html')[0]
        .classList.remove('draggable-column');
      // const event = new CustomEvent(this.tableId + '-column-drop', {detail: this.tableColumns});
      // document.dispatchEvent(event);
    },
    scrollDragEnter(speed) {
      this.tableScrollInterval = setInterval(() => {
        const content = document
          .getElementById(this.tableId)
          ?.querySelector('div');
        if (content) {
          content.scrollLeft += speed;
        }
      });
    },
    scrollDragLeave() {
      clearInterval(this.tableScrollInterval);
    },
    onDragStart(event, tableColumns, indexToMove) {
      this.isColumnDragging = true;
      //saved the original columns for comparasion
      this.tableColumnsOriginal = JSON.stringify(tableColumns);

      event.dataTransfer.effectAllowed = 'move';
      this.indexToMove = indexToMove;
      this.oldIndex = indexToMove;
      this.tableColumns = tableColumns;
      event.currentTarget.classList.add('dragging-column');
      this.isDragging = true;
      //set the data to be transfered
      event.dataTransfer.setData(
        'text/plain',
        JSON.stringify({
          tableColumns: this.tableColumns,
          indexToMove: this.indexToMove,
          tableId: this.tableId,
        }),
      );
      localStorage.setItem(
        'dragInfo',
        JSON.stringify({ tableId: this.tableId }),
      );
      document
        .getElementsByTagName('html')[0]
        .classList.add('draggable-cursor');

      const ghostElement = document.createElement('div');
      ghostElement.id = 'ghost-element';
      ghostElement.classList.add('font-size-14');
      document.body.classList.add('overflow-hidden');

      ghostElement.style.cursor = 'move';
      // if dragging label is not set then use the column label
      if (!this.$options.draggingLabel) {
        const label =
          this.tableColumns[this.indexToMove][this.getDraggingLabelKey()];
        if (label) {
          this.$options.draggingLabel = i18n.t(label);
        }
      }
      ghostElement.innerHTML =
        '<span class="material-icons" style="font-size: 18px">drag_indicator</span>' +
        this.$options.draggingLabel;
      document.body.appendChild(ghostElement);
      event.dataTransfer.setDragImage(ghostElement, 70, 30);
      setTimeout(() => {
        document.body.removeChild(ghostElement);
        document.body.classList.remove('overflow-hidden');
        this.generateScrollDiv();
      }, 1);

      window.addEventListener('dragend', this.onDragEnd);
    },
    onDragEnd(event) {
      if (this.indexToMove == null || this.indexToMove == undefined) return;
      this.scrollDragLeave();
      localStorage.removeItem('dragInfo');
      this.isColumnDragging = false;
      let dropTarget = event.target.parentNode;
      let rect = dropTarget.getBoundingClientRect();
      // if (event.clientX >= rect.left && event.clientX <= rect.right && event.clientY >= rect.top && event.clientY <= rect.bottom) {
      // // if(!event.target.classList.contains('drop-area')) {
      //     this.tableColumnsOriganl = JSON.parse(JSON.stringify(this.tableColumns));
      // } else {
      //     this.tableColumns = JSON.parse(JSON.stringify(this.tableColumnsOriganl));
      //     this.indexToMove = this.oldIndex;
      // }

      window.removeEventListener('dragend', this.onDragEnd);

      let columnToMove = this.tableColumns[this.indexToMove];
      if (!columnToMove) return;
      // get all body columns and add border
      // let elements = document.getElementsByClassName('col_' + columnToMove.name);

      // if(elements && elements.length > 0) {
      //     for(let element of elements) {
      //     element.style.borderLeft  = 'none';
      //     element.style.borderRight  = 'none';
      //     }
      // }
      document
        .getElementsByTagName('html')[0]
        .classList.remove('draggable-cursor');
      document
        .getElementsByClassName('dragging-column')[0]
        ?.classList?.remove('dragging-column');
      this.isDragging = false;

      // if column is not moved then don't dispatch the event
      if (this.tableColumnsOriginal != JSON.stringify(this.tableColumns)) {
        const customEvent = new CustomEvent(this.tableId + '-column-drop', {
          detail: { tableColumns: this.tableColumns, isFromSort: true },
        });
        document.dispatchEvent(customEvent);
      }
      this.lastSwappedIndex = -1;
      this.indexToMove = -1;
      this.$options.draggingLabel = '';
      this.removeScrollDiv();
    },
    onDragOver(event, columnIndex) {
      if (
        !this.canDragDropColumn(this.tableColumns[columnIndex]) ||
        !this.isColumnDragging
      )
        return;
      //Prevent dragover event from being called with wrong table when screen have multiple tables
      let dragInfo = localStorage.getItem('dragInfo');
      if (dragInfo != null) {
        dragInfo = JSON.parse(dragInfo);
        const tableId = dragInfo.tableId;
        const table = event.target.closest('.q-table__container');
        if (table) {
          if (table.id != tableId) {
            return;
          }
        }
      } else {
        return;
      }

      // if column is not moved then don't dispatch the event
      if (this.tableColumnsOriginal != JSON.stringify(this.tableColumns)) {
        const customEvent = new CustomEvent(this.tableId + '-column-drop', {
          detail: { tableColumns: this.tableColumns, isFromSort: true },
        });
        document.dispatchEvent(customEvent);
      }
      this.lastSwappedIndex = -1;
      this.indexToMove = -1;
      this.$options.draggingLabel = '';
      this.removeScrollDiv();
    },
    onDragOver(event, columnIndex) {
      if (
        !this.canDragDropColumn(this.tableColumns[columnIndex]) ||
        !this.isColumnDragging
      )
        return;
      //Prevent dragover event from being called with wrong table when screen have multiple tables
      let dragInfo = localStorage.getItem('dragInfo');
      if (dragInfo != null) {
        dragInfo = JSON.parse(dragInfo);
        const tableId = dragInfo.tableId;
        const table = event.target.closest('.q-table__container');
        if (table) {
          if (table.id != tableId) {
            return;
          }
        }
      } else {
        return;
      }

      event.dataTransfer.effectAllowed = 'move';
      event.dataTransfer.dropEffect = 'move';
      document
        .getElementsByTagName('html')[0]
        .classList.remove('draggable-cursor');

      // dragging behavior checking
      if (this.lastX == event.clientX) return;
      if (this.lastSwappedIndex > -1) {
        const countDifferent = this.lastSwappedIndex - columnIndex;
        if (countDifferent == -1 && this.lastX > event.clientX) {
          this.lastX = event.clientX;
          return;
        }
        if (countDifferent == 1 && this.lastX < event.clientX) {
          this.lastX = event.clientX;
          return;
        }
      }

      let columnToMove = this.tableColumns[this.indexToMove];
      // get all body columns and add border
      // let elements = document.getElementsByClassName('col_' + columnToMove.name);
      // if(elements && elements.length > 0) {
      //     for(let element of elements) {
      //         element.style.borderLeft  = '1px dotted grey';
      //         element.style.borderRight  = '1px dotted grey';
      //     }
      // }

      // if dragging on same element do noting
      if (columnIndex == this.indexToMove) {
        return;
      }
      //remove the old item from old index
      this.tableColumns.splice(this.indexToMove, 1);
      // update Table row object
      this.tableColumns.splice(columnIndex, 0, columnToMove);
      // update the index as column is moved
      this.indexToMove = columnIndex;
      this.lastSwappedIndex = columnIndex;
      this.lastX = event.clientX;
    },
    onDragEnter() {
      this.isDragging = true;
    },
    onDragLeave() {
      this.isDragging = false;
    },
  },
};
